llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Gallopamil, a close verapamil-family analogue sharing the dimethoxyphenethyl-methylamino-propyl scaffold, showed 96.3% oral bioavailability in humans; its high transfer score strongly supports F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Desmethyl verapamil, a secondary-amine verapamil analogue, had 49 ± 14% absolute bioavailability versus IV in healthy men, supporting high oral bioavailability despite formulation differences.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Drotaverine, which contains a dimethoxy-substituted dihydroisoquinoline motif related to the query, had mean absolute oral bioavailability of 58.2 ± 18.2% in volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Vernakalant, a structurally related amino ether, showed 58 ± 19% absolute oral bioavailability in fasted healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Bevantolol, another dimethoxyphenethyl amino alcohol, had mean oral bioavailability of 57% (range 26-98%) versus IV, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Ketobemidone had more than 50% oral bioavailability in human subjects, providing additional supportive evidence for high F, though with lower structural transfer.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "NNC 01-0687 was reported to give high oral bioavailability in humans, qualitatively supporting the high-F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Clomipramine has absolute oral bioavailability of 36-62% in humans, supporting high F but with lower structural similarity to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Verapamil, the closest direct analogue, had mean absolute bioavailability of 19.4% in healthy young men after an 80 mg oral dose versus 10 mg IV, below the 20% threshold; this is the main contradictory evidence, but other verapamil studies report values of 22-52% and the query's lactam modification may reduce first-pass liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer human bioavailability data from close verapamil-family analogues (gallopamil 96%, norverapamil 49%, drotaverine 58%, vernakalant 58-71%) supports F >= 20%. The main contradictory verapamil value (~19-20%) is borderline and is outweighed by the higher-scoring gallopamil evidence and the query's structural modification.",
  "evidence_gaps": [
    "No direct pharmacokinetic study of the exact query molecule is available; prediction relies on close analogues.",
    "Verapamil oral bioavailability is borderline and highly variable (18-52%), making threshold assignment sensitive to formulation, dose, and population.",
    "The effect of the query's cyclic lactam/carbonyl replacement on first-pass metabolism and transporter-mediated clearance is not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

